import{_ as t,c as r,a2 as e,o}from"./chunks/framework.CqbvlPrP.js";const a="/assets/img/stock/%E4%BA%A4%E6%98%93%E8%AE%A4%E7%9F%A5/%E4%BA%A4%E6%98%93%E5%B8%A6%E7%9D%80%E6%AD%A2%E6%8D%9F%E5%8E%BB%E5%A0%B5/2.jpg",m=JSON.parse('{"title":"交易的核心就是在关键点位带上止损赌吗？","description":"","frontmatter":{},"headers":[],"relativePath":"stock/交易认知/交易的核心就是在关键点位带上止损赌吗.md","filePath":"stock/交易认知/交易的核心就是在关键点位带上止损赌吗.md"}'),s={name:"stock/交易认知/交易的核心就是在关键点位带上止损赌吗.md"};function n(i,p,l,h,c,_){return o(),r("div",null,p[0]||(p[0]=[e('<h1 id="交易的核心就是在关键点位带上止损赌吗" tabindex="-1">交易的核心就是在关键点位带上止损赌吗？ <a class="header-anchor" href="#交易的核心就是在关键点位带上止损赌吗" aria-label="Permalink to &quot;交易的核心就是在关键点位带上止损赌吗？&quot;">​</a></h1><p>叶扶摇</p><p>扯到赌，听我讲讲，教你如何做一个合格的赌徒,把握交易真正的核心。</p><p>首先，定义自己是什么类型的赌徒，短线，长线or其他...</p><p><strong>玩短线的，就不要总想着带好止损让利润奔跑...</strong></p><p><strong>玩长线的，就不要总盯着几分钟里的小鱼小虾...</strong></p><p>既要又要还要，是不对的！</p><p>意思就是固定下来你的操作周期，不要轻易切换。</p><p>其次，</p><p><strong>尊重客观事实，再行主观之事...</strong></p><p>比如你一直做的大波段，2H作为你的方向周期，30m是你的入场周期。</p><p>那么2H里一眼望去的趋势就是客观事实，什么是一眼望去的趋势？就是不用你瞎JB画，一眼就能判断出此时是上涨趋势，下跌趋势，还是震荡趋势，但凡花你2分钟都看不明白的，就停下来不要下赌桌！尊重客观事实，就是不要逆着你看到的趋势去赌。</p><p>像此刻的棕榈油--一眼看去是下跌的。</p><p><img src="'+a+'" alt="2H走势图"></p><p>后面怎么走？不知道，不去想不去猜..</p><p>但是此刻抄底做多不是明智的行为，假如后期持续上涨了，你此处做个多，虽然这次赌对了，但是下次还能赌对吗？...</p><p>不抄底不摸顶！</p><p>然后再切到你的进场周期30m，图是这样的：</p><p><img src="'+a+'" alt="30m周期图"></p><p>此时价格突破了红框画的关键阻力区间，未到下个白色框关键阻力区间...</p><p><strong>关键支撑/阻力位如何找？可以看看这个：</strong></p><p>[叶扶摇：支撑位阻力位交易策略，你必须要知道的!] ​(zhuanlan.zhihu.com/p/710312182?utm_psn=1860056121345196032)</p><h2 id="对于这时-你该怎么做" tabindex="-1">对于这时，你该怎么做？ <a class="header-anchor" href="#对于这时-你该怎么做" aria-label="Permalink to &quot;对于这时，你该怎么做？&quot;">​</a></h2><p><strong>最朴素的做法是，等待</strong>。</p><p>等到：</p><p>1.价格到了白色框阻力区间内，找时机做空，止损放在白色框上方（8886上方）。</p><p>2.价格重新回落突破红色框下方，进场做空，止损跟上面1一样。</p><p>3.夜盘开盘半小时，如果收了根阴K，与前一个K形成看跌形态的组合，比如看跌吞没等，进一半做空，3.1价格继续上到白框区间再进一半空，或者3.2价格下破红框区间再进一半空。止损跟1一样。</p><p>这就是行主观之事，</p><p><strong>所谓--尊重客观事实，再行主观之事</strong>，</p><p><strong>就是--大处着眼，小处着手...</strong></p><h2 id="再讲细一点-怎么可以精准的入场-可以看看下面几个" tabindex="-1">再讲细一点，怎么可以精准的入场，可以看看下面几个 <a class="header-anchor" href="#再讲细一点-怎么可以精准的入场-可以看看下面几个" aria-label="Permalink to &quot;再讲细一点，怎么可以精准的入场，可以看看下面几个&quot;">​</a></h2><p>Pinbar战法</p><p>十字星</p><p>看跌吞没，看涨吞没</p><p>然后，</p><h2 id="要考虑赌注该下多少" tabindex="-1">要考虑赌注该下多少？ <a class="header-anchor" href="#要考虑赌注该下多少" aria-label="Permalink to &quot;要考虑赌注该下多少？&quot;">​</a></h2><p>按照点子最背的情况，输50次。</p><p>10W本钱，一次下注2000块，</p><p>然后看上面3个不同进场位与止损位的空间，除以他们，就算出了3种不同进场位置该开的手数。</p><p>至于胜算，抛开你想赢多少不算，2＞3＞1。因为2既顺2H趋势，又顺30m趋势，1顺2H逆30m。。</p><h2 id="最后-考虑的是你能赢多少" tabindex="-1">最后，考虑的是你能赢多少， <a class="header-anchor" href="#最后-考虑的是你能赢多少" aria-label="Permalink to &quot;最后，考虑的是你能赢多少，&quot;">​</a></h2><p>既然喜欢在关键位置赌，</p><p>那么进去后，遇到下一个关键位，多半也会心跳加速，那就在让你心跳加速的位置出来，就在30m里，目光所见的最低点8372出来...</p><p>怎么让心跳不加速？</p><p>大量，复盘，总结，做到心里有数。</p><h2 id="总结" tabindex="-1">总结： <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结：&quot;">​</a></h2><p>如何做一个合格的赌徒，</p><p>1.定义自己是哪种赌徒（选择交易周期）；</p><p>2.只参与看的懂的赌局（看不懂就等待）；</p><p>3.考虑下注多少别梭哈（风控仓位管理）；</p><p>4.能盈多少？（说不好，看自己定规则）。</p><p>所以，回到问题【交易的核心就是在关键位点位带上止损赌吗？】</p><p>答：不全是，起码核心不是。</p>',54)]))}const u=t(s,[["render",n]]);export{m as __pageData,u as default};
